RunLumiDto RunLumiDto::fromJson(const json &j) {
  RunLumiDto rl;
  rl.runNumber = j.value<uint64_t>("runNumber", 0);
  rl.lb = j.value<uint64_t>("lb", 0);
  rl.starttime = j.value<uint64_t>("starttime", 0);
  rl.endtime = j.value<uint64_t>("endtime", 0);
  return rl;
}
